INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('river', 'The wide river', 'The river runs wide and unhurried. The far bank looks like another country.|A heron watches from a stone, entirely unbothered by your problem.', 'Get across the river');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('door', 'The iron door', 'The door is iron, the lock is iron, and the key is nowhere to be seen.|Someone has scratched a joke into the metal. It is not a good joke, but it is a joke.', 'Get through the door');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('bramble', 'The dark trail', 'The path disappears under a tangle of bramble, thick as rope.|Somewhere behind it, something is glowing. It might be a lantern. It might be eyes.', 'Get through the bramble');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('garden', 'The sunken garden', 'The garden has been under water so long that reeds grow through the benches.|A frog holds a staring contest with you. It is winning.', 'Bring the garden back');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('ford', 'The cold ford', 'Every stone in the ford rolls away the moment you trust it.|Your breath makes small clouds, then bigger ones.', 'Cross the ford');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('shore', 'The quiet shore', 'The tide is far out, and the boat is high on the sand.|The sea sounds like it is thinking about something else.', 'Get the boat into the water');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('white-road', 'The white road', 'Snow has buried the road, and the markers with it.|Everything is quiet in the way that means a lot of snow.', 'Find the road');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('night-field', 'The night field', 'The stars are out, but the field is black as a closed eye.|You can hear the grass, but you cannot see it.', 'Find your way across');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('pass', 'The blocked pass', 'A rockfall fills the pass. The stones are the size of sleeping animals.|The wind picks up, considers the situation, and gives up on you.', 'Clear the pass');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('storm', 'The storm road', 'Thunder is walking up the road behind you, taking its time.|The sky has that purple look that means business.', 'Get ahead of the storm');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('grove', 'The fallen grove', 'A storm took the whole grove down. The path is a nest of branches.|A woodpecker is already working on the wreck. Waste not.', 'Make a way through');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('ridge', 'The high ridge', 'The ridge is a wall of grey stone, and the path goes straight up it.|A goat watches from a ledge it should not be able to reach.', 'Get up the ridge');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('field', 'The dry field', 'The field is cracked and pale. Nothing has grown here in a long season.|A single crow inspects your chances.', 'Wake the field');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('market', 'The flooded market', 'The rain has made a river of the market street.|A paper boat sails past with great dignity.', 'Clear the street');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('gate', 'The old gate', 'A gate with no hinge and no key guards the orchard.|The orchard smells like it knows something.', 'Open the gate');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('bell', 'The silent bell', 'A great bronze bell hangs over the square, and the rope has rotted away.|The whole village is waiting, pretending not to.', 'Ring the bell');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('dream', 'The sleeping village', 'Everyone in the village is asleep, and the sun is already high.|A cat is awake, and clearly in charge.', 'Wake the village');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('bridge', 'The broken bridge', 'Half the bridge is gone, and the other half is thinking about it.|Below, the gorge keeps its own counsel.', 'Cross the gorge');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('chest', 'The locked chest', 'A chest sits under the window, locked three times over.|It is humming, very quietly.', 'Open the chest');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('crowd', 'The market crowd', 'The square is packed, and you need to reach the stage.|A juggler has stopped juggling to watch you.', 'Reach the stage');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('lake', 'The frozen lake', 'The lake is frozen, but the ice is soft near the middle.|A fishing hut waits on the far shore, smoke rising.', 'Cross the lake');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('wall', 'The garden wall', 'The wall is old, tall, and just out of reach.|Something on the far side smells like apples.', 'Get over the wall');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('cart', 'The stuck cart', 'A merchant''s cart is wedged deep in the mud.|The merchant is explaining the situation to the ox.', 'Free the cart');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('dark-cave', 'The cave mouth', 'The cave goes down into the dark, and the dark goes further down.|You can hear water somewhere.', 'Find the way down');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('dragon', 'The sleeping dragon', 'The dragon is asleep across the pass, and it is the pass.|Its breathing smells like a foundry.', 'Get past the dragon');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('desert', 'The dry crossing', 'The sand goes on past the horizon, and the horizon is not impressed.|A single bird is following you. It looks hopeful.', 'Cross the desert');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('bell-tower', 'The bell tower', 'The rope is cut, and the bell has not rung in years.|The village below is waiting to know the hour.', 'Ring the bell');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('snow-pass', 'The snow pass', 'The pass is white from wall to wall, and the markers are gone.|A lantern glows further up, very patient.', 'Reach the lantern');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('harbor', 'The storm harbor', 'The boats are pulling at their ropes, and the sky is coming down.|One small boat is still out there.', 'Bring the boat home');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('mill', 'The mill on the stream', 'The wheel groans and does not turn.|A sack of grain has been left on the sill, and it is getting damp.', 'Get the mill wheel turning');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('lantern-hill', 'The lantern hill at dusk', 'The lanterns have gone out one by one.|The path is steep, and the dark is patient.', 'Light the way up the hill');
INSERT INTO seed_puzzle(id, place, lines, prompt) VALUES('frost-garden', 'The frozen garden', 'Everything has gone stiff and white.|A bee is asleep on the fence, which is not a good sign.', 'Wake the garden');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('river', 'water', 'The river rises into a broad, shining step and holds still while you cross.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('river', 'ice', 'The surface goes white and quiet. You walk over a bridge that did not exist a breath ago.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('river', 'snow', 'Snow packs the current into a hard white shelf, wide enough to walk.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('river', 'stone', 'Stones lift out of the shallows one by one and line up into a crossing.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('river', 'earth', 'The riverbed rises under your feet and makes a muddy road.');
