INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'lightning', 'One bright crack and the bolt shears straight through the lock.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'ice', 'The metal goes cold and brittle. One tap and the lock falls apart in clean pieces.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'stone', 'The stones under the threshold shift, and the frame gives you just enough room to squeeze past.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'earth', 'The ground under the door settles, and the whole frame leans open.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'wind', 'Air slides through the keyhole and lifts the latch from the inside.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'hand', 'You knock. Somewhere inside, someone small and kind turns the handle.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('door', 'mind', 'You think very clearly about the door being open, and the lock agrees.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bramble', 'fire', 'The bramble curls back, glowing at the edges, and the path opens, warm and clean.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bramble', 'wind', 'The tangle parts under one sharp gust and stays parted, surprised.');
