INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bramble', 'ice', 'The bramble freezes solid and shatters away in a bright, tinkling rush.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bramble', 'snow', 'A heavy fall bends the branches flat, and you walk over them.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bramble', 'shadow', 'The bramble leans away from your shadow as if it were a cold wind.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('garden', 'earth', 'The ground drinks the water in slow gulps. Benches appear, mossy and dry.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('garden', 'fire', 'The water lifts away in a warm mist, leaving the garden steaming and alive.');
