INSERT INTO seed_solution(puzzle_id, family, text) VALUES('lake', 'wind', 'A steady wind pushes you across, skating lightly.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('lake', 'boat', 'A flat boat slides over the ice like a sled.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'wood', 'A vine leans against the wall and braids itself into a ladder.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'stone', 'Stones lift into a stair, one careful step at a time.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'earth', 'The ground swells into a ramp against the wall.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'wind', 'The air lifts you to the top, and sets you down among the apples.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'animal', 'A broad-backed creature waits by the wall. It knows what you want.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('wall', 'ice', 'A cold stair forms on the stones, bright and steady.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'earth', 'The mud firms and lifts, and the wheels come free.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'stone', 'Flat stones roll under the wheels and the cart climbs out.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'wood', 'Branches shove themselves under the wheels as levers.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'water', 'A channel of water runs under the cart and floats it free.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'animal', 'The ox finally understands, and leans. The cart comes loose.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('cart', 'fire', 'The mud dries hard, and the wheels crack free.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'light', 'A small lamp of clean light floats ahead of you.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'sun', 'A sunbloom follows you into the cave, warm and steady.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'fire', 'A flame walks beside you, low and careful.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'moon', 'Soft moonlight gathers in your palm, enough for one step at a time.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'sound', 'You listen to the water and follow its echo down.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dark-cave', 'time', 'You wait until your eyes forget the daylight. Then you can see.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'dream', 'You slip into its dream and ask it to roll over. It does.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'sound', 'A soft lullaby deepens the sleep, and you walk by.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'wind', 'You float past on a quiet wind, not touching the stone.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'ice', 'Frost settles over the dragon, and its breathing slows further.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'animal', 'Another creature walks up, curls beside it, and makes room for you.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('dragon', 'shadow', 'A shadow covers its eyes, and the dragon never wakes.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'water', 'A spring opens under your feet and follows you across.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'wind', 'A cool wind walks beside you and keeps the sun off.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'cloud', 'A small cloud hangs over you, and it is enough.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'earth', 'The sand firms into a road, and the road goes where you go.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'animal', 'The bird calls, and something larger answers, willing to carry you.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('desert', 'time', 'You walk at night. The crossing takes longer and does not hurt.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'wind', 'A shaped gust swings the clapper, once, cleanly.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'sound', 'You give the bell a note, and it gives one back.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'metal', 'A blade struck on the rim sings out over the roofs.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'lightning', 'A small careful spark jumps, and the bell speaks.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'hand', 'You climb and strike it with the flat of your hand.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('bell-tower', 'person', 'The bellkeeper''s child climbs beside you and rings it properly.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('snow-pass', 'snow', 'The snow packs into steps that carry you up.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('snow-pass', 'ice', 'A frozen stair climbs the slope, bright and sure.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('snow-pass', 'wind', 'The wind clears a corridor through the drift.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('snow-pass', 'sun', 'Warm light melts a path, steaming, then firm.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('snow-pass', 'earth', 'The ground rises in ridges under the snow, showing the way.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'water', 'A wave rises, takes the hull, and carries it to the quay.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'wind', 'You turn the wind and the boat rides it home.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'ice', 'The harbor goes still and glassy, and the boat slides in.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'light', 'A beacon finds the boat and it follows the light home.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'lightning', 'A bolt splits the worst of the storm; the boat slips in behind it.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('harbor', 'animal', 'A great grey swimmer nudges the hull all the way to the stones.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('mill', 'water', 'The stream leans into the paddles, and the wheel begins, slow and sure.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('mill', 'wind', 'A gust finds the sails, and the whole mill wakes with a creak and a sneeze of flour.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('lantern-hill', 'fire', 'A flame rises in the dark and walks ahead of you, low and steady.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('lantern-hill', 'sun', 'The last of the sunlight catches the lanterns, and each one wakes up at once.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('lantern-hill', 'moon', 'The moon finds the path and draws a silver line up the slope, one step at a time.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('frost-garden', 'sun', 'Sunlight pours over the frost, and the garden remembers that it is spring.');
INSERT INTO seed_solution(puzzle_id, family, text) VALUES('frost-garden', 'wind', 'A warm wind comes through and shakes the frost loose like fine dust.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('river', 'fire', 'The water hisses and turns to steam where your spell lands. The river shrugs and keeps flowing.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('river', 'sun', 'Bright light on the water. Very pretty. Still very wet.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('river', 'metal', 'The blade dips into the current and is gone. The river does not care about edges.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('river', '*', 'The river takes your spell and keeps going. It has been doing this for a long time.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('door', 'water', 'The door is now wet and just as closed. The joke is still not funny.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('door', 'wood', 'A green shoot curls around the hinge. It is charming. It does not open the door.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('door', '*', 'The door is unmoved. Even the joke on it looks smug.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bramble', 'water', 'The bramble is now damp and even more stubborn.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bramble', 'stone', 'A rock lands on the bramble and now you have a rock and a bramble.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bramble', '*', 'The bramble closes ranks. Now it looks personal.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('garden', 'stone', 'You drop stones in. Now the garden is wet and has stones in it.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('garden', 'boat', 'The boat is lovely. It does not remove any water.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('garden', '*', 'The water sits there, patient as ever. The frog is still winning.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ford', 'wind', 'The wind pushes at the water. The water pushes back. Nothing is crossed.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ford', 'hand', 'You reach for a stone. It rolls away again, almost apologetically.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ford', '*', 'The current rolls on, unimpressed. Your boots are already wet.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('shore', 'fire', 'A warm glow on the sand. The boat is not moved, but it is now cosy.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('shore', 'ice', 'The shallows freeze. Now the boat is high on ice instead of sand.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('shore', '*', 'The boat stays exactly where it was, and the sea stays exactly where it is.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('white-road', 'water', 'The snow is now wet snow. You have made the problem heavier.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('white-road', 'wood', 'A branch sticks out of a drift. It is a start, not a road.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('white-road', '*', 'The snow absorbs the effort and gives nothing back.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('night-field', 'earth', 'The ground is now nicely lit by nothing at all. You are still in the dark.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('night-field', 'metal', 'A blade glints faintly. Then it stops glinting. Then it is dark again.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('night-field', '*', 'Darkness answers darkness. Nothing else happens.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('pass', 'water', 'The stones get wet. The pass is still blocked, but cleaner.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('pass', 'wood', 'A tree grows beside the rockfall. Nice shade. No path.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('pass', '*', 'The rockfall shifts by a finger''s width and settles again.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('storm', 'fire', 'Your flame gutters in the rain. The storm is not impressed.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('storm', 'boat', 'A boat on a road. Even the storm pauses to judge you.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('storm', '*', 'The storm notices you, which is worse than being ignored.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('grove', 'water', 'The branches are wet now. Heavier, too.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('grove', 'snow', 'Snow on a wreck. It is beautiful. It is still a wreck.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('grove', '*', 'The tangle creaks, settles, and keeps the road closed.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ridge', 'water', 'Water runs down the rock. The rock is now slippery and still tall.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ridge', 'fire', 'The rock glows warm. It is a warm wall. You are still below it.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('ridge', '*', 'The ridge looks down at you. It has done this to better climbers.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('field', 'fire', 'The field is now warm and even drier. The crow is disappointed.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('field', 'metal', 'A blade cuts a neat line in the dust. Nothing grows along it.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('field', '*', 'The field waits. It has waited longer than this.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('market', 'stone', 'You drop stones in the street. The water is higher and now there are stones.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('market', 'animal', 'Something small swims past. It is having a lovely time. The street is still flooded.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('market', '*', 'The water finds your shoes and stays there, delighted.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('gate', 'water', 'The gate is wet. The orchard is still on the other side.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('gate', 'ice', 'The gate is now cold and just as shut.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('gate', '*', 'The gate holds. The orchard keeps its secret.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bell', 'water', 'A splash on bronze. The bell stays quiet.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bell', 'stone', 'A stone bounces off the bell with a dull thud. The village winces.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bell', '*', 'The bronze swallows the sound and offers nothing back.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dream', 'shadow', 'The village gets darker and sleeps even more deeply.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dream', 'ice', 'A cold snap. Everyone pulls the blankets tighter.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dream', '*', 'The village sleeps on. Somewhere the cat sighs.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bridge', 'water', 'The water below is beautiful. It is also very far down.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bridge', '*', 'The gorge takes your spell and gives back an echo.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('chest', 'water', 'The chest is damp and still locked.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('chest', '*', 'The chest rattles once, smugly, and stays shut.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('crowd', 'fire', 'A flame in a crowded market is a bad idea. The crowd moves away from you, not for you.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('crowd', '*', 'The crowd shifts, closes, and carries on its business.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('lake', 'fire', 'The ice thins. Warm, but unhelpful.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('lake', '*', 'The ice creaks under your feet and declines to help.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('wall', 'water', 'The wall is wet. The wall is still tall.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('wall', '*', 'The wall keeps its apples and its silence.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('cart', 'wind', 'The wind pushes the cart deeper. The merchant is not grateful.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('cart', '*', 'The cart digs in deeper. The ox looks embarrassed for you.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dark-cave', 'shadow', 'You make the dark darker. Very impressive. Very unhelpful.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dark-cave', '*', 'The dark is generous. It gives you more dark.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dragon', 'fire', 'The dragon wakes a little, sighs a warm breath, and goes back to sleep. You are now warm.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('dragon', '*', 'The dragon stirs, sighs out a warm breath, and sleeps on.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('desert', 'fire', 'The desert is now hotter. The bird looks personally let down.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('desert', '*', 'The sand takes your spell and returns heat.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bell-tower', 'stone', 'A stone thuds against the bronze. The village winces.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('bell-tower', '*', 'The bell hangs there, enormous and uninterested.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('snow-pass', 'rain', 'The snow turns to slush. Every step is heavier now.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('snow-pass', '*', 'The drift settles into a new shape and stays in the way.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('harbor', 'fire', 'A flame in a storm. The rain puts it out and the boat stays out.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('harbor', '*', 'The storm throws your spell back at the shore.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('mill', 'fire', 'The wheel is not turning for heat. Find something that pushes it.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('mill', 'ice', 'Ice would stop the wheel, not start it. Think about what moves water or air.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('lantern-hill', 'water', 'The lanterns are not going to light from water. Something warm or bright is needed.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('lantern-hill', 'ice', 'Cold will not light a path. Try something that brings light or warmth.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('frost-garden', 'fire', 'The frost is too thick for a little heat. Try something gentler and wider.');
INSERT INTO seed_hint(puzzle_id, family, text) VALUES('frost-garden', 'water', 'Water would only freeze again here. Something dry and bright is needed.');
