-- Authored puzzle seeds. One block per place; each solution is one honest way through.
-- tools/spells/build_puzzles.py expands these into app/src/main/assets/puzzles.db.

CREATE TABLE seed_puzzle(id TEXT PRIMARY KEY, place TEXT NOT NULL, lines TEXT NOT NULL, prompt TEXT NOT NULL);
CREATE TABLE seed_solution(puzzle_id TEXT NOT NULL, family TEXT NOT NULL, text TEXT NOT NULL, PRIMARY KEY(puzzle_id, family, text));
CREATE TABLE seed_hint(puzzle_id TEXT NOT NULL, family TEXT NOT NULL, text TEXT NOT NULL, PRIMARY KEY(puzzle_id, family));



